import type { LogModel } from "@/generated/prisma-sqlite/models";
import type { LOG_KINDS, LOG_LEVELS } from "@/src/shared/lib/schemas/logs";

/** Which kind of event an entry records: on the server, or by the user. */
export type LogKind = (typeof LOG_KINDS)[number];

/** How severe an entry is. */
export type LogLevel = (typeof LOG_LEVELS)[number];

/** A log entry as it crosses to the client: plain, serialisable, no Prisma types. */
export interface LogEntryDTO {
  /** Unique identifier, generated by the database. */
  id: string;
  /** ISO 8601 timestamp of when the entry was written. */
  createdAt: string;
  /** Whether it records something on the server or something the user did. */
  kind: LogKind;
  /** How severe it is. */
  level: LogLevel;
  /** A stable machine-readable name, such as `task.deleted`. */
  event: string;
  /** A human-readable line describing it. */
  message: string;
  /** Context recorded with the entry, or null when it has none.
   *
   * Stored text that is not a JSON object comes back as `{ unparsed: <the text> }`,
   * so one damaged row cannot stop the rest from being read.
   */
  detail: Record<string, unknown> | null;
}

/** Reads a stored `detail` back into an object.
 *
 * @param stored The column's text, or null when the entry has no detail.
 * @returns The object it holds, or the text kept under `unparsed` when it is not a JSON object.
 */
function parseDetail(stored: string | null): Record<string, unknown> | null {
  if (stored === null) return null;
  try {
    const value: unknown = JSON.parse(stored);
    if (typeof value === "object" && value !== null && !Array.isArray(value)) {
      return value as Record<string, unknown>;
    }
  } catch {
    // Not JSON at all: kept as it was stored, below.
  }
  return { unparsed: stored };
}

/** Converts a log row into the shape a client can receive.
 *
 * @param model The log row as Prisma returns it.
 * @returns The same entry, serialisable, with its detail parsed.
 */
export function toLogEntryDTO(model: LogModel): LogEntryDTO {
  return {
    id: model.id,
    createdAt: model.createdAt.toISOString(),
    kind: model.kind as LogKind,
    level: model.level as LogLevel,
    event: model.event,
    message: model.message,
    detail: parseDetail(model.detail),
  };
}
